//   STLport vector<C3DVector>(size_type) 0x007C2AB0 (CArray<C3DVector>(n) forwards to it, engine/CArray.h FABLE_RETAIL_CARRAY),
//   vector<C3DVector>::operator= 0x0075B8D0, free 0x00BFEA14 (the local array's storage).
